    12	/// A table schema, which specifies its data structure and constraints.
    13	///
    14	/// Tables can't change after they are created. There is no ALTER TABLE nor
    15	/// CREATE/DROP INDEX, only CREATE TABLE and DROP TABLE.
    16	#[derive(Clone, Debug, PartialEq, Deserialize, Serialize)]
    17	pub struct Table {
    18	    /// The table name. Unique identifier for the table. Can't be empty.
    19	    pub name: String,
    20	    /// The primary key column index. A table must have a primary key, and it
    21	    /// can only be a single column.
    22	    pub primary_key: usize,
    23	    /// The table's columns. Must have at least one.
    24	    pub columns: Vec<Column>,
    25	}
    26	
    27	impl encoding::Value for Table {}
    28	
    29	/// A table column.
    30	#[derive(Clone, Debug, PartialEq, Deserialize, Serialize)]
    31	pub struct Column {
    32	    /// Column name. Can't be empty.
    33	    pub name: String,
    34	    /// Column datatype.
    35	    pub datatype: DataType,
    36	    /// Whether the column allows null values. Not legal for primary keys.
    37	    pub nullable: bool,
    38	    /// The column's default value. If None, the user must specify an explicit
    39	    /// value. Must match the column datatype. Nullable columns require a
    40	    /// default (often Null). Null is only a valid default when nullable.
    41	    pub default: Option<Value>,
    42	    /// Whether the column should only allow unique values (ignoring NULLs).
    43	    /// Must be true for a primary key column. Requires index.
    44	    pub unique: bool,
    45	    /// Whether the column should have a secondary index. Must be false for
    46	    /// primary keys, which are the primary index. Must be true for unique or
    47	    /// reference columns.
    48	    pub index: bool,
    49	    /// If set, this column is a foreign key reference to the given table's
    50	    /// primary key. Must be of the same type as the target primary key.
    51	    /// Requires index.
    52	    pub references: Option<String>,
    53	}
    54	
    55	// Formats the table as a SQL CREATE TABLE statement.
    56	impl Display for Table {
    57	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    58	        /// Formats an identifier as valid SQL, quoting it if necessary.
    59	        fn format_ident(ident: &str) -> String {
    60	            match is_ident(ident) {
    61	                true => ident.to_string(),
    62	                false => format!("\"{}\"", ident.replace('\"', "\"\"")),
    63	            }
    64	        }
    65	
    66	        writeln!(f, "CREATE TABLE {} (", format_ident(&self.name))?;
    67	        for (i, column) in self.columns.iter().enumerate() {
    68	            write!(f, "  {} {}", format_ident(&column.name), column.datatype)?;
    69	            if i == self.primary_key {
    70	                write!(f, " PRIMARY KEY")?;
    71	            } else if !column.nullable {
    72	                write!(f, " NOT NULL")?;
    73	            }
    74	            if let Some(default) = &column.default {
    75	                write!(f, " DEFAULT {default}")?;
    76	            }
    77	            if i != self.primary_key {
    78	                if column.unique {
    79	                    write!(f, " UNIQUE")?;
    80	                }
    81	                if column.index {
    82	                    write!(f, " INDEX")?;
    83	                }
    84	            }
    85	            if let Some(reference) = &column.references {
    86	                write!(f, " REFERENCES {reference}")?;
    87	            }
    88	            if i < self.columns.len() - 1 {
    89	                write!(f, ",")?;
    90	            }
    91	            writeln!(f)?;
    92	        }
    93	        write!(f, ")")
    94	    }
    95	}
