    97	impl Table {
    98	    /// Validates the table schema, using the catalog to validate foreign key
    99	    /// references.
   100	    pub fn validate(&self, catalog: &impl Catalog) -> Result<()> {
   101	        if self.name.is_empty() {
   102	            return errinput!("table name can't be empty");
   103	        }
   104	        if self.columns.is_empty() {
   105	            return errinput!("table has no columns");
   106	        }
   107	        if self.columns.get(self.primary_key).is_none() {
   108	            return errinput!("invalid primary key index");
   109	        }
   110	
   111	        for (i, column) in self.columns.iter().enumerate() {
   112	            if column.name.is_empty() {
   113	                return errinput!("column name can't be empty");
   114	            }
   115	            let (cname, ctype) = (&column.name, &column.datatype); // for formatting convenience
   116	
   117	            // Validate primary key.
   118	            let is_primary_key = i == self.primary_key;
   119	            if is_primary_key {
   120	                if column.nullable {
   121	                    return errinput!("primary key {cname} cannot be nullable");
   122	                }
   123	                if !column.unique {
   124	                    return errinput!("primary key {cname} must be unique");
   125	                }
   126	                if column.index {
   127	                    return errinput!("primary key {cname} can't have an index");
   128	                }
   129	            }
   130	
   131	            // Validate default value.
   132	            match column.default.as_ref().map(|v| v.datatype()) {
   133	                None if column.nullable => {
   134	                    return errinput!("nullable column {cname} must have a default value");
   135	                }
   136	                Some(None) if !column.nullable => {
   137	                    return errinput!("invalid NULL default for non-nullable column {cname}");
   138	                }
   139	                Some(Some(vtype)) if vtype != column.datatype => {
   140	                    return errinput!("invalid default type {vtype} for {ctype} column {cname}");
   141	                }
   142	                Some(_) | None => {}
   143	            }
   144	
   145	            // Validate unique index.
   146	            if column.unique && !column.index && !is_primary_key {
   147	                return errinput!("unique column {cname} must have a secondary index");
   148	            }
   149	
   150	            // Validate references.
   151	            if let Some(reference) = &column.references {
   152	                if !column.index && !is_primary_key {
   153	                    return errinput!("reference column {cname} must have a secondary index");
   154	                }
   155	                let reftype = if reference == &self.name {
   156	                    self.columns[self.primary_key].datatype
   157	                } else if let Some(target) = catalog.get_table(reference)? {
   158	                    target.columns[target.primary_key].datatype
   159	                } else {
   160	                    return errinput!("unknown table {reference} referenced by column {cname}");
   161	                };
   162	                if column.datatype != reftype {
   163	                    return errinput!(
   164	                        "can't reference {reftype} primary key of {reference} from {ctype} column {cname}"
   165	                    );
   166	                }
   167	            }
   168	        }
   169	        Ok(())
   170	    }
   171	
   172	    /// Validates a row, including uniqueness and reference checks using the
   173	    /// given transaction.
   174	    ///
   175	    /// If update is true, the row replaces an existing entry with the same
   176	    /// primary key. Otherwise, it is an insert. Primary key changes are
   177	    /// implemented as a delete+insert.
   178	    ///
   179	    /// Validating uniqueness and references individually for each row is not
   180	    /// performant, but it's fine for our purposes.
   181	    pub fn validate_row(&self, row: &Row, update: bool, txn: &impl Transaction) -> Result<()> {
   182	        if row.len() != self.columns.len() {
   183	            return errinput!("invalid row size for table {}", self.name);
   184	        }
   185	
   186	        // Validate primary key.
   187	        let id = &row[self.primary_key];
   188	        let idslice = &row[self.primary_key..=self.primary_key];
   189	        if id.is_undefined() {
   190	            return errinput!("invalid primary key {id}");
   191	        }
   192	        if !update && !txn.get(&self.name, idslice)?.is_empty() {
   193	            return errinput!("primary key {id} already exists");
   194	        }
   195	
   196	        for (i, (column, value)) in self.columns.iter().zip(row).enumerate() {
   197	            let (cname, ctype) = (&column.name, &column.datatype);
   198	            let valueslice = &row[i..=i];
   199	
   200	            // Validate datatype.
   201	            if let Some(ref vtype) = value.datatype()
   202	                && vtype != ctype
   203	            {
   204	                return errinput!("invalid datatype {vtype} for {ctype} column {cname}");
   205	            }
   206	            if value == &Value::Null && !column.nullable {
   207	                return errinput!("NULL value not allowed for column {cname}");
   208	            }
   209	
   210	            // Validate outgoing references.
   211	            if let Some(target) = &column.references {
   212	                match value {
   213	                    // NB: NaN is not a valid primary key, and not valid as a
   214	                    // missing foreign key marker.
   215	                    Value::Null => {}
   216	                    v if target == &self.name && v == id => {}
   217	                    v if txn.get(target, valueslice)?.is_empty() => {
   218	                        return errinput!("reference {v} not in table {target}");
   219	                    }
   220	                    _ => {}
   221	                }
   222	            }
   223	
   224	            // Validate uniqueness constraints. Unique columns are indexed.
   225	            if column.unique && i != self.primary_key && !value.is_undefined() {
   226	                let mut index = txn.lookup_index(&self.name, &column.name, valueslice)?;
   227	                if update {
   228	                    index.remove(id); // ignore existing version of this row
   229	                }
   230	                if !index.is_empty() {
   231	                    return errinput!("value {value} already in unique column {cname}");
   232	                }
   233	            }
   234	        }
   235	        Ok(())
   236	    }
   237	}
